const data = msg.payload.data;
// Buffer also supplied by Modbus implementation, enables reading and writing
// signed integers, floats etc.
const buffer = msg.payload.buffer;
// Address offset
const offset = 0x6006;

const running = Boolean(data[0x6006 - offset] & 1<<3);
const fault = Boolean(data[0x6006 - offset] & 1<<6);
const heatsink_temp = 0.1 * data[0x6007 - offset];
const hs_voltage = 0.1 * data[0x6008 - offset];
const ls_voltage = 0.1 * data[0x600C - offset];
// Signed 16-Bit integer can be read from Node.js Buffer returned by Modbus implementation
const ls_current = 0.1 * buffer.readInt16BE(2*(0x600D - offset));
const ls_power_kw = 0.1 * buffer.readInt16BE(2*(0x600E - offset));
const ambient_temp = 0.1 * data[0x600F - offset];
const derated_power_kw = 0.1 * data[0x6010 - offset];
const mppt_boost_uncontrolled_rectification_closure = Boolean(data[0x6011 - offset]);
const dehumidification_running = Boolean(data[0x6012 - offset]);
const insulation_resistance_pos_megohm = 0.001 * data[0x6013 - offset];
const insulation_resistance_neg_megohm = 0.001 * data[0x6014 - offset];
const insulation_detections_ctr = data[0x6015 - offset];
const insulation_detection_running = Boolean(data[0x6016 - offset]);

msg.payload = {
    running,
    fault,
    heatsink_temp,
    hs_voltage,
    ls_voltage,
    ls_current,
    ls_power_kw,
    ambient_temp,
    derated_power_kw,
    mppt_boost_uncontrolled_rectification_closure,
    dehumidification_running,
    insulation_resistance_pos_megohm,
    insulation_resistance_neg_megohm,
    insulation_detections_ctr,
    insulation_detection_running
};
return msg;

const dcdc_get_regs = global.get("dcdc_get_regs");

return dcdc_get_regs(
    // Address offset or first register to read
    offset = 0x6006,
    // End register to read
    reg_end = 0x6016,
);

const dcdc_set_reg = global.get("dcdc_set_reg");
const to_int16_complement = global.get("to_int16_complement");

return dcdc_set_reg(0x6107, to_int16_complement(10 * msg.payload));

const dcdc_set_reg = global.get("dcdc_set_reg");
const to_int16_complement = global.get("to_int16_complement");

return dcdc_set_reg(0x6106, to_int16_complement(10 * msg.payload));

const data = msg.payload.data;
// Buffer also supplied by Modbus implementation, enables reading and writing
// signed integers, floats etc.
const buffer = msg.payload.buffer;
// Address offset
const offset = 0x6100;

const ls_voltage_setpoint = 0.1 * data[0x6100 - offset];
const ls_ovp = 0.1 * data[0x6101 - offset];
const ls_uvp = 0.1 * data[0x6102 - offset];
const hs_voltage_setpoint = 0.1 * data[0x6103 - offset];
const hs_ovp = 0.1 * data[0x6104 - offset];
const hs_uvp = 0.1 * data[0x6105 - offset];
const power_setpoint = 0.1 * buffer.readInt16BE(2 * (0x6106 - offset));
const current_setpoint = 0.1 * buffer.readInt16BE(2 * (0x6107 - offset));
const mpp_open_circuit_voltage = 0.1 * data[0x6108 - offset];
const autostart_enabled = Boolean(data[0x6109 - offset]);
const dcdc_enabled = Boolean(data[0x610A - offset]);
const parameters_fixed = Boolean(data[0x610B - offset]);
const power_limit = 0.1 * data[0x610D - offset];
const current_limit = 0.1 * data[0x610E - offset];

return [
    { payload: dcdc_enabled },
    { payload: autostart_enabled },
    { payload: parameters_fixed },
    { payload: ls_voltage_setpoint },
    { payload: current_setpoint },
    { payload: hs_voltage_setpoint },
    { payload: power_setpoint },
    { payload: ls_ovp },
    { payload: ls_uvp },
    { payload: hs_ovp },
    { payload: hs_uvp },
    { payload: power_limit },
    { payload: current_limit },
];

const dcdc_get_regs = global.get("dcdc_get_regs");

return dcdc_get_regs(
    // Address offset or first register to read
    offset = 0x6100,
    // End register to read
    reg_end = 0x610E,
);

// Bit 1 in HW Fault Word 1 is EPO <==> Emergency Power Off.
// HV Interlock State Active (green) means no EPO or interlock state closed.
const interlock_closed = (msg.payload.data[0] & 1<<0) === 0;

msg.payload = interlock_closed;

return msg;

const data = msg.payload.data;
// Buffer also supplied by Modbus implementation, enables reading and writing
// signed integers, floats etc.
const buffer = msg.payload.buffer;
// Address offset
const offset = 0x6020;

const hw_fault_1 = data[0x6020 - offset];
const hw_fault_2 = data[0x6021 - offset];
const dcdc_fault = data[0x6022 - offset];
const hv_side_fault = data[0x6023 - offset];
const paralleling_fault = data[0x6024 - offset];
const system_fault = data[0x6025 - offset];
const switch_fault = data[0x6026 - offset];
const other_fault = data[0x6027 - offset];

msg.payload = {
    hw_fault_1,
    hw_fault_2,
    dcdc_fault,
    hv_side_fault,
    paralleling_fault,
    system_fault,
    switch_fault,
    other_fault
};

return msg;

const dcdc_get_regs = global.get("dcdc_get_regs");

return dcdc_get_regs(
    // Address offset or first register to read
    offset = 0x6020,
    // End register to read
    reg_end = 0x6027,
);

const dcdc_set_reg = global.get("dcdc_set_reg");

const power_setpoint_kw = 5.0;

return dcdc_set_reg(0x6110, 10 * power_setpoint_kw);

const dcdc_set_reg = global.get("dcdc_set_reg");

const value = 1;

return dcdc_set_reg(0x6113, value);

const dcdc_set_reg = global.get("dcdc_set_reg");
/** Protocol description according to a datasheet with bad translation.
 * Flag descriptions can change.
 * Firmware can change.
 */

// Bit 0: Enable delayed undervoltage protection (UVP)
const enable_delayed_uvp = 1;
// Bit 1: 0 for UVP delay on low side, 1 for UVP on high side.
const uvp_delay_ls_hs_switch = 0;
// "Bit 2: Enable constant voltage mode after constant current/constant power mode
// (effective when DCDCMode is 1)" (FIXME: ??? They mean "at" CC/CP?)
const enable_cv_mode_after_cc_cp = 1;
// Bit 3: DCDC CC/CV selection. 0: CC. 1: CV.
const cc_cv_switch = 0;
// Bit 4: DCDC CP/CC selection (constant power - constant current). 0: CP. 1: CC.
const cp_cc_switch = 1;
// Bit 6: Enable DCDC Mode.
const enable_dcdc_mode = 1;
// Bit 8: Enable high side positive/negative bus software balancing control
const enable_hs_balancing = 0;
// Bit 9: Enable MPPT Filtering
const enable_mppt_filtering = 0;
// Bit 10: DCDC voltage control. 0: Low side voltage control. 1: High side voltage contro
const dcdc_cv_ls_hs_switch = 0;
// "Bit 11: Enable bidirectional DCDC voltage control current" (FIXME: ???)
const enable_bidi_dcdc_voltage_control_current = 1;
// Bit 12: Enable MPPT Boost Charging
const enable_mppt_boost_charging = 0;
// Bit 13-14: DCDC mode selection.
// 0b00: MPPT, 0b01: NoSYNC, 0b10: SYNC.
const dcdc_mode = 0b01;
// Bit 15: MPPT mode selection 0: Boost MPPT, 1: Buck MPPT
const mppt_mode = 0;


const value = (
      enable_delayed_uvp << 0
    | uvp_delay_ls_hs_switch << 1
    | enable_cv_mode_after_cc_cp << 2
    | cc_cv_switch << 3
    | cp_cc_switch << 4
    | enable_dcdc_mode << 6
    | enable_hs_balancing << 8
    | enable_mppt_filtering << 9
    | dcdc_cv_ls_hs_switch << 10
    | enable_bidi_dcdc_voltage_control_current << 11
    | enable_mppt_boost_charging << 12
    | dcdc_mode << 13
    | mppt_mode << 15
)

return dcdc_set_reg(0x610C, value);

const dcdc_set_reg = global.get("dcdc_set_reg");

// INT16, Read/Write, quickly and easily configure DCDC mode at address 0x610C:
// 0- No effect
// 1- Constant voltage (current) on the high voltage side
// 2- Constant voltage (power) on the high voltage side
// 3- Constant voltage (current) on the low voltage side
// 4- Constant voltage (power) on the low voltage side
// 5- Battery charging and discharging (current)
// 6- Battery charging and discharging(power)
// 7- Vanadium REDOX flow battery charging and discharging (current)
// 8- Vanadium REDOX flow battery charging and discharging (power)
// 9- Boost MPPT
// 10- Boost MPPT (with precharge)
// 11- Step-down MPPT

const operation_mode = 5;

return dcdc_set_reg(0x611D, operation_mode);

// Function node: detect bus-off and trigger recovery
if (msg.payload.err && msg.payload.canid === 0x00000040) {
    msg.reason = "bus-off detected";
    return msg;
}
return null;

/** Decode raw CAN input frame received from ACDC HW Controller.
 * 
 * FIXME: No Security or Integrity Checking.
 * 
 * This receives frames with integrity protected by HW.
 * There is NO secure filtering of invalid input rames, only HW safety.
 * 
 * Possibly implement further frame ID or integrity error checking
 * for increased reliability, otherwise security is TBD.
 * 
 **/


// This is the controller or gateway ID (this application)
const CAN_ID_CONTROLLER = 0xF0;
// Enable this to listen to all traffic
const PROMISCUOUS_MODE = false;

// Infypower uses a 29-Bit CAN Extended Frame ID for additional information
const CAN_MASK_SRC = 0xFF;
const CAN_MASK_DEST = 0xFF << 8;
const CAN_MASK_CMD = 0b111111 << 16;
const CAN_MASK_DEVICE = 0b1111 << 22;
const CAN_MASK_ERROR = 0b111 << 26;

const dest_id = (msg.payload.canid & CAN_MASK_DEST) >> 8;

// Reject all frames not addressed to us
if (! PROMISCUOUS_MODE && dest_id !== CAN_ID_CONTROLLER) {
    return;
}

// Decode more data encoded in Infypower 29-Bit CAN Extended Frame ID
const src_id = msg.payload.canid & CAN_MASK_SRC;
const command = (msg.payload.canid & CAN_MASK_CMD) >> 16;
const device_no = (msg.payload.canid & CAN_MASK_DEVICE) >> 22;
const error_code = (msg.payload.canid & CAN_MASK_ERROR) >> 26;
let error_str = "";
if (error_code == 0x02) {
    error_str = "Command Invalid";
} else if (error_code == 0x03) {
    error_str = "Data Invalid";
} else if (error_code == 0x07) {
    error_str = "In Start Processing";
}

msg.payload = {
    src_id,
    dest_id,
    command,
    device_no,
    error_code,
    error_str,
    data: msg.payload.data,
    rawData: msg.payload.rawData
}

return msg;

/* Send Command to Individual Device or Broadcast ID.

This takes the below shown message scheme and creates the
data frame for sending with node-red-socketcan node.

msg.payload = {
    dest_id: 0x3F,
    command: 0x01,
    data: [0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00],
};

*/

// Controller or gateway address number, default is 0xF0
const ID_CONTROLLER = 0xF0;
// Device number indicating the dest address is a single device or broadcast ID
const DEV_NO_SINGLE = 0x0A;


const infypower_can_id = (
    // Source ID
    ID_CONTROLLER
    // Dest ID
    | (msg.payload.dest_id & 0xFF) << 8
    // Command no
    | (msg.payload.command & 0b111111) << 16
    // Device no
    | DEV_NO_SINGLE << 22
    // Error code is zero for outgoing commands
);

msg.payload = {
    canid: infypower_can_id,
    data: msg.payload.data,
    dlc: msg.payload.data.length,
    ext: true,
    canfd: false,
    rtr: false,
};

return msg;

// Reject internal communication frame between modules
const CAN_BASE_INTERNAL_COM = 0x0757F800;
const CAN_MASK_INTERNAL_COM = 0xFFFFFF00;
let id = msg.payload.canid & CAN_MASK_INTERNAL_COM;
if (id == CAN_BASE_INTERNAL_COM) {
    return;
}

// Reject frames from this or other controller/gateway
const CAN_BASE_CONTROLLER = 0xF0;
const CAN_END_CONTROLLER = 0xF8;
const CAN_MASK_SRC = 0xFF;
id = msg.payload.canid & CAN_MASK_SRC;
if (id >= CAN_BASE_CONTROLLER && id <= CAN_END_CONTROLLER) {
    return;
}

/* Send Group CMD to CAN-connected chargers.

This takes the below shown message scheme and creates the
data frame for sending with node-red-socketcan node.

msg.payload = {
    group_id: 0x00,
    command: 0x01,
    data: [0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00],
};

*/

// This is the controller or gateway address number, default is 0xF0
const ID_CONTROLLER = 0xF0;
// Device number indicating dest address is a group address
const DEV_NO_GROUP = 0x0B


const infypower_can_id = (
    // Source ID
    ID_CONTROLLER
    // Dest ID
    | (msg.payload.group_id & 0xFF) << 8
    // Command No
    | (msg.payload.command & 0b111111) << 16
    // Device No
    | DEV_NO_GROUP << 22
    // Error code is zero for outgoing commands
);

msg.payload = {
    canid: infypower_can_id,
    data: msg.payload.data,
    dlc: msg.payload.data.length,
    ext: true,
    canfd: false,
    rtr: false,
}

return msg;

msg.payload = {
    // Broadcast address
    dest_id: 0x3F,
    // Read system information, voltage and current
    command: 0x01,
    data: [0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00],
};
return msg;

// All other messages are rejected.
if (msg.payload.command != 0x01) {
    return;
}

const voltage = msg.payload.rawData.readFloatBE();
const current = msg.payload.rawData.readFloatBE(4);

return [
    {topic: "Voltage", payload: voltage},
    {topic: "Current", payload: current},
];

// All other messages are rejected.
if (msg.payload.command != 0x02) {
    return;
}

const n_modules = msg.payload.data[2];

return {topic: "System Module Count", payload: n_modules};

msg.payload = {
    // Broadcast address
    dest_id: 0x3F,
    command: 0x02,
    data: [0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00],
};
return msg;

// All other messages are rejected.
if (msg.payload.command != 0x04) {
    return;
}

const group_id = msg.payload.data[2];
const temperature = msg.payload.rawData.readInt8(4);
const hw_state = msg.payload.data.splice(5, 8);

return [
    { topic: "Group", payload: group_id },
    { topic: "Temperature", payload: temperature },
    { topic: "State", payload: hw_state },
];

// For systems with only one module
const MODULE_ID = 0x00;

msg.payload = {
    // Destination address
    dest_id: MODULE_ID,
    // Read system information, current and voltage
    command: 0x04,
    data: [0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00],
};
return msg;

// Enable outputs if msg.payload is true

const enable_flags = msg.payload ? 0x00 : 0x01;

msg.payload = {
    // Broadcast address
    dest_id: 0x3F,
    command: 0x1A,
    data: [enable_flags, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00],
};
return msg;

const v_sp = flow.get("voltage_setpoint");
const i_sp = flow.get("current_setpoint");

if (v_sp === undefined || i_sp === undefined) {
    node.error("Received undefined setpoint value");
    return;
};

const buffer = Buffer.allocUnsafe(8);
buffer.writeUInt32BE(v_sp * 1000);
buffer.writeUInt32BE(i_sp * 1000, 4);

msg.payload = {
    // Broadcast address
    dest_id: 0x3F,
    command: 0x1B,
    data: Array.from(buffer.values()),
};
return msg;

// For systems with only one module
const MODULE_ID = 0x00;

msg.payload = {
    dest_id: MODULE_ID,
    command: 0x06,
    data: [0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00],
};
return msg;

// For systems with only one module
const MODULE_ID = 0x00;

msg.payload = {
    dest_id: MODULE_ID,
    command: 0x0A,
    data: [0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00],
};
return msg;

// All other messages are rejected.
if (msg.payload.command != 0x06) {
    return;
}

const v_ab = 0.1 * msg.payload.rawData.readUInt16BE();
const v_bc = 0.1 * msg.payload.rawData.readUInt16BE(2);
const v_ca = 0.1 * msg.payload.rawData.readUInt16BE(4);

return [
    { topic: "v_ab", payload: v_ab },
    { topic: "v_bc", payload: v_bc },
    { topic: "v_ca", payload: v_ca },
    { topic: "v_avg", payload: 1/3 * (v_ab + v_bc + v_ca) },
];

// All other messages are rejected.
if (msg.payload.command != 0x0A) {
    return;
}

const v_max = msg.payload.rawData.readUInt16BE();
const v_min = msg.payload.rawData.readUInt16BE(2);
const i_max = 0.1 * msg.payload.rawData.readUInt16BE(4);
const p_max = 10 * msg.payload.rawData.readUInt16BE(6);

return {
    payload: {
        v_max,
        v_min,
        i_max,
        p_max
    },
    topic: "Operating Range Margins",
};

