/**** Global Function Definitions ****/

/**
 * Convert input number to 16-Bit two's complement value.
 * 
 * Out-of-range input values are clipped to valid range.
 * 
 * @param {number} value Input number in range - (2**15) ... 2**15 - 1.
 * @return {number} 16-Bit two's complement value as an unsigned integer number.
*/
function to_int16_complement(value) {
    const int16_min = - (2 ** 15);
    const int16_max = 2 ** 15 - 1;
    const value_lim = Math.min(Math.max(value, int16_min), int16_max);

    // Only in node.js: Using node.js Buffer object.
    // See: https://nodejs.org/api/buffer.html#buffer
    const buf = Buffer.allocUnsafe(2);
    buf.writeInt16BE(value_lim);
    return buf.readUInt16BE();

    // Generally available:
    //const arr_buf = new ArrayBuffer(2);
    //const buf_view = new DataView(arr_buf);
    //buf_view.setInt16(0, value_lim, false);
    //return buf_view.getUint16(0, false);
}

/**
 * Build Message to Query DCDC Converter using Modbus Interface
 * 
 * Configure read of one or count consequtive Modbus registers
 * from the input starting address. Each register is 16 Bit wide.
 * 
 * @param {number} reg_offset Modbus Register Address Start.
 * @param {number} reg_end Last Modbus Register Address to read.
 * @return {object} Query message to send to modbus Flex-Getter node.
 */
function dcdc_get_regs(reg_offset, reg_end = reg_offset) {
    const msg = {
        payload: {
            fc: 3,
            unitid: 1,
            address: reg_offset,
            quantity: 1 + reg_end - reg_offset,
        },
        topic: "dcdc_get_regs",
    };
    return msg;
}

/**
 * Build Message to Set DCDC Converter Register using Modbus Interface
 * 
 * Configure read of one Modbus register
 * from the input starting address.
 * 
 * @param {number} reg Modbus Register Address.
 * @param {number} value Value to write.
 * @return {object} Query message to send to modbus Flex-Write node.
 */
function dcdc_set_reg(reg, value) {
    const msg = {
        payload: {
            fc: 6,
            unitid: 1,
            address: reg,
            quantity: 1,
            value,
        },
        topic: "dcdc_set_reg",
    };
    return msg;
}


global.set("to_int16_complement", to_int16_complement);
global.set("dcdc_get_regs", dcdc_get_regs);
global.set("dcdc_set_reg", dcdc_set_reg);
